#[test]
fn lux() {
    for v in [1.0, 0.3, -42.75, 1e6, 123456.789] {
        // Generated conversion vs. the upstream formula, verbatim.
        let x: f64 = v;
        let base = x;
        assert_close(Illuminance::from_lux(v).as_base(), base, F64_TOL);
        let x: f64 = base;
        let back = x;
        assert_close(Illuminance::from_base(base).as_lux(), back, F64_TOL);
        assert_close(Illuminance::from_lux(v).as_lux(), v, ROUND_TRIP_TOL);
        // f32 storage.
        assert_close(
            Illuminance::from_lux(v as f32).as_base() as f64,
            base,
            F32_TOL,
        );
        assert_close(
            Illuminance::from_base(base as f32).as_lux() as f64,
            back,
            F32_TOL,
        );
    }
}

